// Committed so a clean checkout (and CI) can typecheck; expo-env.d.ts itself is
// generated by `expo start` and gitignored.
/// <reference types="expo/types" />

// Metro resolves image imports to an asset reference usable as an <Image> source
declare module "*.png" {
  const source: import("react-native").ImageSourcePropType;
  export default source;
}
